/**
 * @module ai/aireviewcore/types
 */
export interface AIReviewCheckBaseDefinition {
    id: string;
    commandId: string;
    title: string;
    description: string;
    isParameterized: boolean;
    isExtra?: boolean;
}
export interface AIReviewCheckDefinition extends AIReviewCheckBaseDefinition {
    useArgs?: boolean;
    options?: Array<AIReviewCheckOptions>;
    args?: Record<string, string>;
}
export interface AIReviewCheckExtraDefinition extends AIReviewCheckBaseDefinition {
    isExtra: true;
    prompt: string;
    model?: string;
}
export type AIReviewCheckOptions = {
    formType: string;
    label?: string;
    default?: string;
    data?: Array<AIReviewCheckOptionData>;
    argsKey?: string;
};
export type AIReviewCheckOptionData = {
    label: string;
    id: string;
};
